import { describe, it, expect } from 'vitest';
import { buildInvoiceReminders } from '@/lib/derived/invoiceReminders';
import { outstandingByClient } from '@/lib/derived/outstanding';
import { buildClients, buildRevenue, buildServices } from '@/scripts/demo/revenue';

const MID = new Date(2026, 9, 13);   // an ordinary mid-month run
const FIRST = new Date(2027, 0, 1);  // New Year's Day: the shortest window

// amount_eur is generated by Postgres; mirror its rule (amount × ex_rate) here.
const eur = (e: { amount: string; exRate?: string }) => Number(e.amount) * Number(e.exRate ?? 1);

function remindersOn(today: Date) {
  const clients = buildClients(today);
  const lookup = Object.fromEntries(clients.map((c) => [c.id!, c.clientName]));
  const muted = clients.filter((c) => c.remindersMutedAt).map((c) => c.id!);
  const rows = buildRevenue(today).revenueEntries.map((e) => ({ ...e, amountEur: eur(e) }));
  return buildInvoiceReminders(rows, lookup, today, muted);
}

describe('demo revenue', () => {
  for (const today of [MID, FIRST]) {
    it(`shows every Invoice Reminders state on ${today.toDateString()}`, () => {
      const { reminders, muted } = remindersOn(today);
      expect(new Set(reminders.map((r) => r.status))).toEqual(new Set(['issued', 'not_yet', 'overdue']));
      expect(muted.map((m) => m.client)).toEqual(['Kitepoint Labs']);
    });
  }

  it('never dates an invoice or a payment after today', () => {
    for (const e of buildRevenue(MID).revenueEntries) {
      expect(e.dateInvoice <= '2026-10-13').toBe(true);
      if (e.datePaid) expect(e.datePaid <= '2026-10-13').toBe(true);
    }
  });

  it('spans January last year to today', () => {
    const months = [...new Set(buildRevenue(MID).revenueEntries.map((e) => e.dateInvoice.slice(0, 7)))].sort();
    expect(months[0]).toBe('2025-01');
    expect(months.at(-1)).toBe('2026-10');
  });

  it('leaves some invoices unpaid, an older one among them, so Outstanding has content', () => {
    const entries = buildRevenue(MID).revenueEntries;
    const unpaid = entries.filter((e) => !e.fundsReceived);
    expect(unpaid.length).toBeGreaterThanOrEqual(5);
    expect(unpaid.some((e) => e.dateInvoice < '2026-09-01')).toBe(true);
    const names = Object.fromEntries(buildClients(MID).map((c) => [c.id!, c.clientName]));
    expect(outstandingByClient(unpaid.map((e) => ({ ...e, amountEur: eur(e) })), names).length).toBeGreaterThanOrEqual(3);
    for (const e of entries.filter((x) => x.fundsReceived)) {
      expect(e.paymentMethod).toBeTruthy();
      expect(e.datePaid).toBeTruthy();
    }
  });

  it('runs at small-agency scale: €35–60k of revenue in a full month', () => {
    const sep = buildRevenue(MID).revenueEntries
      .filter((e) => e.dateInvoice.startsWith('2026-09'))
      .reduce((s, e) => s + eur(e), 0);
    expect(sep).toBeGreaterThan(35000);
    expect(sep).toBeLessThan(60000);
  });

  it('splits every invoice across services to the cent', () => {
    const { revenueEntries, revenueLineItems } = buildRevenue(MID);
    const services = new Set(buildServices().map((s) => s.id));
    for (const e of revenueEntries) {
      const lines = revenueLineItems.filter((l) => l.revenueEntryId === e.id);
      expect(lines.length).toBeGreaterThan(0);
      expect(lines.reduce((s, l) => s + Number(l.amount), 0)).toBeCloseTo(Number(e.amount), 2);
      for (const l of lines) expect(services.has(l.serviceId!)).toBe(true);
    }
  });

  it('numbers invoices in its own OS- series, without repeats', () => {
    const nums = buildRevenue(MID).revenueEntries.map((e) => e.invoiceNumber!);
    expect(new Set(nums).size).toBe(nums.length);
    for (const n of nums) expect(n).toMatch(/^OS-\d{4}-\d{4}$/);
  });

  it('is deterministic for a given day', () => {
    expect(buildRevenue(MID)).toEqual(buildRevenue(MID));
  });
});
